@startuml

class OilWell {
  + code : string
}

class OnshoreWell extends OilWell {
  + surfaceExtension : float
}

class OffshoreWell extends OilWell {
  + yearOfInstallation : int
  + geographicalArea : Area
}

class Area {
  + code : string
  + environmentalImportance : int
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class Extraction {
  + quantity : float
}

OilWell "0..*" -- "0..*" Company : extraction
(OilWell, Company) -- "1" Extraction

@enduml

